static void ultrasonic_sensor_eventqueue_init(ultrasonic_sensor_eventqueue * eq, ultrasonic_sensor_event *buffer, sc_integer capacity)
{
	eq->events = buffer;
	eq->capacity = capacity;
	eq->push_index = 0;
	eq->pop_index = 0;
	eq->size = 0;
}

static sc_integer ultrasonic_sensor_eventqueue_size(ultrasonic_sensor_eventqueue * eq)
{
	return eq->size;
}

static ultrasonic_sensor_event ultrasonic_sensor_eventqueue_pop(ultrasonic_sensor_eventqueue * eq)
{
	ultrasonic_sensor_event event;
	if(ultrasonic_sensor_eventqueue_size(eq) <= 0) {
		ultrasonic_sensor_event_init(&event, Ultrasonic_Sensor_invalid_event);
	}
	else {
		event = eq->events[eq->pop_index];
		
		if(eq->pop_index < eq->capacity - 1) {
			eq->pop_index++;
		} 
		else {
			eq->pop_index = 0;
		}
		eq->size--;
	}
	return event;
}
static sc_boolean ultrasonic_sensor_eventqueue_push(ultrasonic_sensor_eventqueue * eq, ultrasonic_sensor_event ev)
{
	if(ultrasonic_sensor_eventqueue_size(eq) == eq->capacity) {
		return bool_false;
	}
	else {
		eq->events[eq->push_index] = ev;
		
		if(eq->push_index < eq->capacity - 1) {
			eq->push_index++;
		}
		else {
			eq->push_index = 0;
		}
		eq->size++;
		
		return bool_true;
	}
}
static void ultrasonic_sensor_event_init(ultrasonic_sensor_event * ev, Ultrasonic_SensorEventID name)
{
	ev->name = name;
}

static void ultrasonic_Sensor_add_event_to_queue(ultrasonic_sensor_eventqueue * eq, Ultrasonic_SensorEventID name)
{
	ultrasonic_sensor_event event;
	ultrasonic_sensor_event_init(&event, name);
	ultrasonic_sensor_eventqueue_push(eq, event);
}

